## Creatable with Popover

When filtering options in a dropdown yields no matches, you can turn the empty state into a creation action. By listening to the <kbd>Return</kbd> key (`Enter`) on the input and rendering an interactive creation trigger with `<moul-kbd>↵</moul-kbd>`, users can seamlessly create and select custom options:

<ComponentPreview>
  <moul-autocomplete placeholder="Create or search..."><moul-autocomplete-item value="tag1">Tag 1</moul-autocomplete-item></moul-autocomplete>
</ComponentPreview>

```tsx



export function CreatablePopoverExample() {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  const [items, setItems] = useState([
    { id: 'react', name: 'React', description: 'Component-based UI library' },
    { id: 'vue', name: 'Vue', description: 'Progressive JavaScript framework' },
    { id: 'svelte', name: 'Svelte', description: 'Cybernetically enhanced web apps' },
    { id: 'solid', name: 'Solid', description: 'Simple and performant reactivity' },
    { id: 'angular', name: 'Angular', description: 'Enterprise frontend platform' },
  ]);

  const trimmedQuery = query.trim();
  const matchingItems = items.filter((item) =>
    item.name.toLowerCase().includes(trimmedQuery.toLowerCase())
  );
  const isNoResults = trimmedQuery.length > 0 && matchingItems.length === 0;

  const handleCreate = (name: string) => {
    const clean = name.trim();
    if (!clean) return;

    const id = clean.toLowerCase().replace(/\s+/g, '-');
    const existing = items.find(
      (item) => item.id === id || item.name.toLowerCase() === clean.toLowerCase()
    );

    if (!existing) {
      const newItem = {
        id,
        name: clean,
        description: 'User-created framework',
      };
      setItems((prev) => [...prev, newItem]);
      setSelectedKey(id);
    } else {
      setSelectedKey(existing.id);
    }

    setQuery('');
    setIsOpen(false);
  };

  return (
    <moul-autocomplete>
      <moul-search-field
        aria-label="Filter or create framework"
        placeholder="Search or create framework..."
        value={query}
        onChange={(val) => {
          setQuery(val);
          if (!isOpen) setIsOpen(true);
        }}
        onFocus={() => setIsOpen(true)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && isNoResults) {
            e.preventDefault();
            handleCreate(query);
          }
        }}
      />
      <div
        isOpen={isOpen}
        onOpenChange={setIsOpen}
        isNonModal
      >
        <div
          aria-label="Frameworks"
          selectionMode="single"
          selectedKeys={selectedKey ? [selectedKey] : []}
          onSelectionChange={(keys) => {
            const [first] = Array.from(keys);
            if (first) setSelectedKey(String(first));
            setIsOpen(false);
          }}
          variant="borderless"
          renderEmptyState={() => (
            <div class="p-1">
              <button
                type="button"
                onClick={() => handleCreate(query)}
                class="w-full flex items-center justify-between gap-2 px-3 py-2 text-sm rounded cursor-pointer transition-colors text-left hover:bg-[var(--moul-color-bg-subtle,#f4f4f5)] dark:hover:bg-neutral-800"
                style={{ color: tokens.colorFg }}
              >
                <span class="flex items-center gap-2 truncate">
                  <span
                    class="w-4 h-4 flex items-center justify-center rounded-full text-xs font-bold shrink-0"
                    style={{
                      backgroundColor: tokens.colorPrimary50,
                      color: tokens.colorPrimary700,
                    }}
                  >
                    +
                  </span>
                  <span class="truncate">
                    Create <strong class="font-semibold">&ldquo;{trimmedQuery}&rdquo;</strong>
                  </span>
                </span>
                <span class="flex items-center gap-1 shrink-0 text-xs text-neutral-400">
                  <span class="text-[10px]">Press</span>
                  <moul-kbd>↵</moul-kbd>
                </span>
              </button>
            </div>
          )}
        >
          {items.map((item) => (
            <moul-autocomplete-item
              key={item.id}
              id={item.id}
              description={item.description}
            >
              {item.name}
            </moul-autocomplete-item>
          ))}
        </div>
      </div>
    </moul-autocomplete>
  );
}
```

