## TanStack Table Integration

Connect `@moul-dev/ui` table primitives with `@tanstack/react-table` for multi-column sorting, row selection, filtering, and pagination:

```tsx




interface Service {
  id: string;
  name: string;
  region: string;
  status: string;
  latency: string;
}

const columnHelper = createColumnHelper<code>&lt;Service&gt;</code>();

export default function TanStackTableExample({ data }: { data: Service[] }) {
  const [sorting, setSorting] = useState<code>&lt;SortingState&gt;</code>([]);
  const [rowSelection, setRowSelection] = useState<code>&lt;RowSelectionState&gt;</code>({});

  const columns = useMemo(
    () => [
      columnHelper.display({
        id: 'select',
        header: ({ table }) => (
          <moul-checkbox
            aria-label="Select all"
            isSelected={table.getIsAllPageRowsSelected()}
            isIndeterminate={table.getIsSomePageRowsSelected()}
            onChange={(val) => table.toggleAllPageRowsSelected(val)}
          />
        ),
        cell: ({ row }) => (
          <moul-checkbox
            aria-label="Select row"
            isSelected={row.getIsSelected()}
            onChange={(val) => row.toggleSelected(val)}
          />
        ),
      }),
      columnHelper.accessor('name', {
        header: 'Service Name',
        cell: (info) => info.getValue(),
      }),
      columnHelper.accessor('region', {
        header: 'Region',
        cell: (info) => info.getValue(),
      }),
      columnHelper.accessor('status', {
        header: 'Status',
        cell: (info) => info.getValue(),
      }),
      columnHelper.accessor('latency', {
        header: 'Latency',
        cell: (info) => info.getValue(),
      }),
    ],
    []
  );

  const table = useTable({
    data,
    columns,
    state: { sorting, rowSelection },
    onSortingChange: setSorting,
    onRowSelectionChange: setRowSelection,
    getCoreRowModel: createCoreRowModel(),
    getSortedRowModel: createSortedRowModel(),
    getFilteredRowModel: createFilteredRowModel(),
    getPaginationRowModel: createPaginatedRowModel(),
  });

  return (
    <moul-table stickyHeader>
      <thead>
        {table.getHeaderGroups().map((headerGroup) => (
          <tr key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <th
                key={header.id}
                sortDirection={header.column.getIsSorted()}
                onSort={
                  header.column.getCanSort()
                    ? header.column.getToggleSortingHandler()
                    : undefined
                }
              >
                {header.isPlaceholder
                  ? null
                  : flexRender(
                      header.column.columnDef.header,
                      header.getContext()
                    )}
              </th>
            ))}
          </tr>
        ))}
      </thead>
      <tbody>
        {table.getRowModel().rows.map((row) => (
          <tr key={row.id} selected={row.getIsSelected()}>
            {row.getVisibleCells().map((cell) => (
              <td key={cell.id}>
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </moul-table>
  );
}
```

