## Large Dataset Virtualization (TanStack Virtual)

Render thousands of table rows with smooth 60fps windowing using `@tanstack/react-virtual`:

<ComponentPreview>
  <moul-table striped><table class="table"><thead><tr><th>ID</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>Active</td></tr></tbody></table></moul-table>
</ComponentPreview>

```tsx




export function VirtualTableExample({ data }: { data: any[] }) {
  const parentRef = useRef<code>&lt;HTMLDivElement&gt;</code>(null);

  const rowVirtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 40,
    overscan: 10,
  });

  const virtualRows = rowVirtualizer.getVirtualItems();
  const totalSize = rowVirtualizer.getTotalSize();
  const paddingTop = virtualRows.length > 0 ? virtualRows[0].start || 0 : 0;
  const paddingBottom =
    virtualRows.length > 0
      ? totalSize - (virtualRows[virtualRows.length - 1].end || 0)
      : 0;

  return (
    <div ref={parentRef} style={{ maxHeight: '360px', overflowY: 'auto' }}>
      <moul-table stickyHeader dense wrapInContainer={false}>
        <thead>
          <tr>
            <th>Hostname</th>
            <th>IP Address</th>
            <th align="numeric">CPU</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {paddingTop > 0 && (
            <tr>
              <td style={{ height: `${paddingTop}px` }} colSpan={4} />
            </tr>
          )}
          {virtualRows.map((virtualRow) => {
            const item = data[virtualRow.index];
            return (
              <tr key={item.id}>
                <td>{item.hostname}</td>
                <td>{item.ip}</td>
                <td align="numeric">{item.cpu}</td>
                <td>{item.status}</td>
              </tr>
            );
          })}
          {paddingBottom > 0 && (
            <tr>
              <td style={{ height: `${paddingBottom}px` }} colSpan={4} />
            </tr>
          )}
        </tbody>
      </moul-table>
    </div>
  );
}
```

